import {api} from './auth.js';
import {bankLogo} from './finance-bank-header.js';
import {upgradeCashback,compareBanks} from './cashback-model.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function startCashback(root,user){
 const style=document.createElement('link');style.rel='stylesheet';style.href='/finance.css';document.head.insertBefore(style,document.querySelector('link[href="./vysota-theme.css"]'));
 const loaded=await api('/api/cashback');let data=upgradeCashback(loaded.data),revision=loaded.revision;
 const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Novosibirsk',year:'numeric',month:'2-digit'}).formatToParts(new Date());
 let period=parts.find(p=>p.type==='year').value+'-'+parts.find(p=>p.type==='month').value,timer,busy=false,pending=false,dirty=false,failed=false,view='categories',search='';
 const monthNames=Array.from({length:12},(_,i)=>new Date(2026,i,1).toLocaleDateString('ru-RU',{month:'long'}));
 const orderedBanks=()=>data.banks.filter(b=>!b.hidden).sort((a,b)=>data.sortMode==='manual'?0:compareBanks(a,b,entries()));
 const matchesSearch=b=>!search.trim()||(entries()[b.id]||[]).some(r=>r.name.toLocaleLowerCase('ru').includes(search.trim().toLocaleLowerCase('ru')));
 function filterCards(){let count=0;root.querySelectorAll('.cashback-card').forEach(c=>{const b=data.banks.find(b=>b.id===c.dataset.bank);c.hidden=!matchesSearch(b);if(!c.hidden)count++;c.querySelectorAll('tbody [data-index]').forEach(row=>{const r=(entries()[b.id]||[])[Number(row.dataset.index)];row.hidden=!!search.trim()&&!r?.name.toLocaleLowerCase('ru').includes(search.trim().toLocaleLowerCase('ru'));});c.querySelector('[data-add-row]').hidden=locked()||!!search.trim();c.querySelectorAll('[data-remove]').forEach(e=>e.hidden=locked()||!!search.trim());});const empty=root.querySelector('#cashback-search-empty');if(empty)empty.hidden=!search.trim()||count>0;}
 const locked=()=>data.lockedMonths.includes(period);
 const favorite=name=>data.favorites.some(n=>n.toLocaleLowerCase('ru')===name.trim().toLocaleLowerCase('ru'));
 const entries=()=>data.months[period]||{};
 function status(text){const notice=root.querySelector('#cashback-status');notice.textContent=text;notice.hidden=['Сохранение…','Все изменения сохранены','Есть несохранённые изменения'].includes(text);root.querySelector('#cashback-retry').hidden=!failed;}
 const recordedNames=()=>Object.values(data.months).flatMap(m=>Object.values(m).flatMap(rows=>rows.map(r=>r.name.trim()).filter(Boolean)));
 function cleanCategories(){const used=new Set(recordedNames().map(n=>n.toLocaleLowerCase('ru'))),names=[...new Set(data.categories.map(n=>n.trim()).filter(Boolean))];data.categories=names.filter(n=>used.has(n.toLocaleLowerCase('ru'))||favorite(n)||!names.some(other=>other.length>n.length&&other.toLocaleLowerCase('ru').startsWith(n.toLocaleLowerCase('ru')))).sort((a,b)=>a.localeCompare(b,'ru'));}
 function history(){return data.categories;}
 function suggestions(){root.querySelector('#cashback-categories').innerHTML=history().map(c=>`<option value="${esc(c)}"></option>`).join('');}
 function remember(name){if(!name?.trim())return;data.categories=[...new Set([...data.categories,name.trim()])];cleanCategories();}
 const oldCategories=JSON.stringify(data.categories);data.categories=[...new Set([...data.categories,...recordedNames()])];cleanCategories();dirty=oldCategories!==JSON.stringify(data.categories);
 function sortCards(){const grid=root.querySelector('#cashback-cards');if(grid?.contains(document.activeElement))return;if(grid)orderedBanks().forEach(b=>{const card=[...grid.children].find(e=>e.dataset.bank===b.id);if(card)grid.append(card);});}
 function valid(){return data.banks.every(b=>b.name.trim())&&Object.values(data.months).every(m=>Object.values(m).every(rows=>rows.every(r=>r.percent===null||Number.isFinite(r.percent)&&r.percent>=0&&r.percent<=100)));}
 function changed(){dirty=true;failed=false;status(valid()?'Сохранение…':'Укажите название банка и процент от 0 до 100.');clearTimeout(timer);timer=setTimeout(save,650);}
 async function save(){clearTimeout(timer);if(busy){pending=true;return;}if(!dirty)return;if(!valid()){status('Укажите название банка и процент от 0 до 100.');return;}busy=true;pending=false;failed=false;status('Сохранение…');const snapshot=structuredClone(data);
  try{const result=await api('/api/cashback',{method:'PUT',body:JSON.stringify({revision,data:snapshot})});revision=result.revision;dirty=JSON.stringify(data)!==JSON.stringify(snapshot);status(dirty?'Сохранение…':'Все изменения сохранены');}
  catch(e){failed=true;status(e.message+' Введённые данные остаются на экране.');}
  finally{busy=false;if(!failed&&(pending||dirty))save();}
 }
 const rowsFor=id=>{data.months[period]??={};return data.months[period][id]??=[];};
 function card(b){const rows=entries()[b.id]||[];return `<section class="panel cashback-card" data-bank="${b.id}"><h2 class="cashback-bank-title">${bankLogo(b.logo)}<span>${esc(b.name)}</span></h2><table class="cashback-rows"><thead><tr><th>Категория</th><th>%</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-index="${i}" class="${favorite(r.name)?'cashback-favorite':''}"><td><input data-category ${locked()?'disabled':''} maxlength="150" list="cashback-categories" value="${esc(r.name)}" placeholder="Название категории" aria-label="Категория ${esc(b.name)}"></td><td><input data-percent ${locked()?'disabled':''} type="number" min="0" max="100" step="0.01" value="${r.percent??''}" aria-label="Процент ${esc(b.name)}"></td><td><button ${locked()?'hidden disabled':''} data-remove="${i}" aria-label="Удалить категорию">×</button></td></tr>`).join('')}</tbody></table><button data-add-row ${locked()?'hidden disabled':''}>＋ Категория</button></section>`;}
 function settings(){return `<section class="panel"><h2>Порядок банков</h2><label class="field">Сортировка<select id="cashback-sort-mode"><option value="auto" ${data.sortMode==='auto'?'selected':''}>Автоматически по категориям</option><option value="manual" ${data.sortMode==='manual'?'selected':''}>Мой порядок</option></select></label><div class="cashback-bank-order">${data.banks.map((b,i)=>`<div class="row between cashback-order-row"><span>${esc(b.name)}${b.hidden?' · скрыт':''}</span><span><button data-move-bank="${b.id}" data-step="-1" ${i===0?'disabled':''} aria-label="${esc(b.name)} выше">↑</button><button data-move-bank="${b.id}" data-step="1" ${i===data.banks.length-1?'disabled':''} aria-label="${esc(b.name)} ниже">↓</button></span></div>`).join('')}</div></section><section class="panel"><h2>Редактирование месяца</h2><p>${esc(monthNames[Number(period.slice(5))-1])} ${period.slice(0,4)} · ${locked()?'Месяц сохранён и закрыт для изменений':'Редактирование открыто'}</p>${locked()?'<button id="cashback-unlock" class="secondary">Разрешить редактирование месяца</button>':''}</section><section class="panel"><h2>Избранные категории</h2><div class="cashback-favorites">${history().map(n=>`<label><input type="checkbox" data-favorite="${esc(n)}" ${favorite(n)?'checked':''}> ${esc(n)}</label>`).join('')||'<p>Сначала добавьте категории в карточки банков.</p>'}</div></section><div class="row between"><h2>Банки</h2><button id="cashback-add-bank" class="primary">＋ Банк</button></div><div id="cashback-bank-settings">${data.banks.map(b=>`<fieldset class="settings-block" data-bank="${b.id}"><legend>${esc(b.name)||'Новый банк'}</legend><label class="field">Название<input data-bank-name maxlength="100" value="${esc(b.name)}"></label><label class="field">Логотип<select data-logo>${[['sber','Сбер'],['t','Т-Банк'],['alfa','Альфа-Банк'],['ozon','OZON Банк'],['gazprom','Газпромбанк'],['vtb','ВТБ'],['yandex','Яндекс'],['generic','Другой банк']].map(([k,l])=>`<option value="${k}" ${b.logo===k?'selected':''}>${l}</option>`).join('')}</select></label><label><input data-visible type="checkbox" ${b.hidden?'':'checked'}> Показывать в списке</label></fieldset>`).join('')}</div>`;}
 function render(){const years=[...new Set([Number(period.slice(0,4)),Number(parts.find(p=>p.type==='year').value),...Object.keys(data.months).map(m=>Number(m.slice(0,4)))])].sort((a,b)=>b-a);
 root.innerHTML=`<header class="topbar"><a class="brand" href="/" style="text-decoration:none;color:inherit">Высота<em>.</em></a><button id="cashback-logout">Выйти</button></header><main class="portal"><h1>Кэшбэки</h1><nav class="fin-nav"><button data-view="categories" class="${view==='categories'?'selected':''}">Категории</button><button data-view="banks" class="${view==='banks'?'selected':''}">Настройки</button></nav><div class="row cashback-filters"><label class="fin-filter">Год<select id="cashback-year">${years.map(y=>`<option ${y===Number(period.slice(0,4))?'selected':''}>${y}</option>`).join('')}</select></label><label class="fin-filter">Месяц<select id="cashback-month">${monthNames.map((m,i)=>`<option value="${String(i+1).padStart(2,'0')}" ${i+1===Number(period.slice(5))?'selected':''}>${m}</option>`).join('')}</select></label></div>${view==='categories'?`<label class="field cashback-search">Найти категорию<input id="cashback-search" list="cashback-categories" value="${esc(search)}" placeholder="Например: Аптеки" maxlength="150" type="search"></label>`:''}<p id="cashback-status" role="status" hidden>${busy?'Сохранение…':dirty?'Есть несохранённые изменения':'Все изменения сохранены'}</p><button id="cashback-retry" hidden>Повторить сохранение</button><datalist id="cashback-categories"></datalist>${view==='banks'?settings():`<div class="row between">${locked()?'':'<button id="cashback-lock" class="primary">Сохранить месяц</button>'}</div><div id="cashback-cards">${orderedBanks().map(card).join('')}</div><p id="cashback-search-empty" hidden>В выбранном месяце категория не найдена среди отображаемых банков.</p>${data.banks.every(b=>b.hidden)?'<p>Все банки скрыты. Включите их в настройках банков.</p>':''}`}<p><button id="cashback-export">Скачать резервную копию</button></p></main>`;
 suggestions();filterCards();root.querySelector('#cashback-search')?.addEventListener('input',e=>{search=e.target.value;filterCards();});
 root.querySelector('#cashback-sort-mode')?.addEventListener('change',e=>{data.sortMode=e.target.value;changed();});
 root.querySelectorAll('[data-move-bank]').forEach(e=>e.onclick=()=>{const i=data.banks.findIndex(b=>b.id===e.dataset.moveBank),j=i+Number(e.dataset.step);if(j<0||j>=data.banks.length)return;[data.banks[i],data.banks[j]]=[data.banks[j],data.banks[i]];data.sortMode='manual';changed();render();});
 root.querySelector('#cashback-lock')?.addEventListener('click',async()=>{if(!valid()){status('Исправьте поля перед сохранением месяца.');return;}if(Object.values(entries()).some(rows=>rows.some(r=>!r.name.trim()||r.percent===null))){status('Заполните название и процент в каждой добавленной строке или удалите пустые строки.');return;}const selected=period;data.lockedMonths.push(selected);dirty=true;clearTimeout(timer);render();while(busy)await new Promise(r=>setTimeout(r,50));await save();if(failed){data.lockedMonths=data.lockedMonths.filter(m=>m!==selected);dirty=true;render();status('Месяц не закрыт: сохранение не удалось. Повторите сохранение.');}else render();});
 root.querySelector('#cashback-unlock')?.addEventListener('click',()=>{data.lockedMonths=data.lockedMonths.filter(m=>m!==period);changed();render();});
 root.querySelectorAll('[data-favorite]').forEach(e=>e.onchange=()=>{data.favorites=data.favorites.filter(n=>n.toLocaleLowerCase('ru')!==e.dataset.favorite.toLocaleLowerCase('ru'));if(e.checked)data.favorites.push(e.dataset.favorite);changed();});
 root.querySelectorAll('[data-view]').forEach(e=>e.onclick=()=>{if(!valid()||failed)return;save();view=e.dataset.view;render();});
 root.querySelectorAll('.cashback-card').forEach(c=>{c.addEventListener('input',e=>{const row=e.target.closest('[data-index]');if(!row||locked())return;const r=rowsFor(c.dataset.bank)[Number(row.dataset.index)];if(e.target.matches('[data-category]')){r.name=e.target.value;row.classList.toggle('cashback-favorite',favorite(r.name));}else if(e.target.matches('[data-percent]'))r.percent=e.target.value===''?null:Number(e.target.value);changed();});c.addEventListener('focusout',e=>{if(e.target.matches('[data-category]')){remember(e.target.value);changed();}suggestions();setTimeout(()=>{if(!c.contains(document.activeElement))sortCards();},0);});c.querySelector('[data-add-row]').onclick=()=>{rowsFor(c.dataset.bank).push({name:'',percent:null});changed();render();const next=root.querySelector(`[data-bank="${c.dataset.bank}"] tbody tr:last-child input`);next?.focus();};c.querySelectorAll('[data-remove]').forEach(e=>e.onclick=()=>{rowsFor(c.dataset.bank).splice(Number(e.dataset.remove),1);changed();render();});});
 root.querySelectorAll('#cashback-bank-settings [data-bank]').forEach(f=>{const b=data.banks.find(b=>b.id===f.dataset.bank);f.querySelector('[data-bank-name]').oninput=e=>{b.name=e.target.value;f.querySelector('legend').textContent=b.name||'Новый банк';changed();};f.querySelector('[data-logo]').onchange=e=>{b.logo=e.target.value;changed();};f.querySelector('[data-visible]').onchange=e=>{b.hidden=!e.target.checked;changed();};});
 root.querySelector('#cashback-add-bank')?.addEventListener('click',()=>{if(!valid())return;const b={id:crypto.randomUUID(),name:'Новый банк',logo:'generic',hidden:false};data.banks.push(b);changed();render();root.querySelector(`[data-bank="${b.id}"] [data-bank-name]`).focus();});
 const change=next=>{if(failed||!valid()){status('Сначала исправьте поля и сохраните изменения или скачайте резервную копию.');return;}save();period=next;render();};
 root.querySelector('#cashback-year').onchange=e=>change(e.target.value+period.slice(4));root.querySelector('#cashback-month').onchange=e=>change(period.slice(0,5)+e.target.value);
 root.querySelector('#cashback-retry').onclick=save;
 root.querySelector('#cashback-export').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({format:'money-cashback-backup-v2',data},null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='cashback-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
 root.querySelector('#cashback-logout').onclick=async()=>{if(dirty||busy){status('Дождитесь сохранения данных перед выходом.');return;}await api('/api/auth/logout',{method:'POST',body:'{}'});location.href='/';};
 }
 window.addEventListener('beforeunload',e=>{if(dirty||busy){e.preventDefault();e.returnValue='';}});render();if(dirty)timer=setTimeout(save,650);
}
